    queue = [v for v in graph if indegree[v] == 0]  # 零入度
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if len(order) < len(graph):
        return None  # 存在环
    return order

