def prefix_function(s):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]   # 失配沿 π 链回退
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def kmp_search(text, pat):
    pi = prefix_function(pat)
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pat[j]:
            j = pi[j-1]   # 失配跳转，i 不动
        if text[i] == pat[j]:
            j += 1
        if j == len(pat):
            return i - j + 1
    return -1

