class Queue:
    def enqueue(self, x):  # 队尾入队 O(1)
        self.items.append(x)
    def dequeue(self):     # 队首出队 O(1)
        if self.is_empty():
            raise IndexError('underflow')
        return self.items.pop(0)
    def front(self):       # 查看队首 O(1)
        return self.items[0]

class CircularQueue:
    def __init__(self, k):
        self.cap = k + 1        # 牺牲一格
        self.data = [None] * self.cap
        self.front = 0
        self.rear = 0
    def enqueue(self, x):
        if (self.rear + 1) % self.cap == self.front:
            raise OverflowError('full')
        self.data[self.rear] = x
        self.rear = (self.rear + 1) % self.cap
    def dequeue(self):
        if self.front == self.rear:
            raise IndexError('underflow')
        v = self.data[self.front]
        self.front = (self.front + 1) % self.cap
        return v
